function levelOrder(root) {
  const queue = root ? [root] : [], levels = [] //@init
  while (queue.length) { //@loop
    const size = queue.length, level = [] //@size
    for (let i = 0; i < size; i++) {
      const node = queue.shift(); level.push(node.val) //@pop
      for (const child of [node.left, node.right]) if (child) queue.push(child) //@push
    }
    levels.push(level) //@level
  }
  return levels //@done
}

