from collections import deque

def solve(root):
    if not root:
        return []
    queue, out = deque([root]), []
    while queue:
        level = []
        for _ in range(len(queue)):  # only this level's nodes
            node = queue.popleft()
            level.append(node['val'])
            for child in (node['left'], node['right']):
                if child:
                    queue.append(child)  # next level waits behind
        out.append(level)
    return out

