function minDepth(root) {
  if (!root) return 0
  let queue = [root]
  let depth = 1
  while (queue.length) {
    const next = []
    for (const node of queue) {
      if (!node.left || !node.right) return depth
      next.push(node.left, node.right)
    }
    queue = next
    depth++
  }
  return depth
}

